/bin/zsh -lc "./run_python -c 'import pathlib, tempfile, app
with tempfile.TemporaryDirectory() as d:
 p=pathlib.Path(d)/\"q.db\"; q=app.Queue(p); q.put(\"job\", {\"a\": [1, {\"b\": True}]})
 first=q.claim(\"same\", 0, 0.5); assert first[\"expires_at\"] == 0.5
 second=q.claim(\"same\", 0.5, 1); assert second[\"receipt\"] "'!= first["receipt"]
 q2=app.Queue(p); assert q2.ack(first["receipt"], 0.5) is False
 assert q2.ack(second["receipt"], 0.5) is True
 assert q.ack(second["receipt"], 0.5) is False
 try: q.put("job", 9)
 except ValueError: pass
 else: raise AssertionError("completed ID was reused")
 q.put("copy", {"v": [1]}); got=q.claim("w", 2, 1); got["payload"]["v"].append(2)
 assert q.claim("w2", 2, 1) is None
 again=q.claim("w2", 3, 1); assert again["payload"] == {"v": [1]}
 r=app.Queue(pathlib.Path(d)/"other.db"); r.put("safe", "ok")
 for value in (True, False, 0, -1, float("inf"), float("nan")):
  try: r.claim("w", 4, value)
  except ValueError: pass
  else: raise AssertionError(f"invalid lease accepted: {value!r}")
 assert r.claim("w", 4, 1)["payload"] == "ok"
 try: r.put("bad", object())
 except TypeError: pass
 else: raise AssertionError("unsupported payload accepted")
 assert r.claim("w", 5, 1) is None
print("queue contract checks passed")'"' && ./run_python smoke.py"

